const maskPrivacyInvitations = `-- name: MaskPrivacyInvitations :execrows
UPDATE taxpayer_invitations SET email = $1, revoked_at = COALESCE(revoked_at, accepted_at, NOW())
WHERE organization_id = $2 AND engagement_id = $3
`

type MaskPrivacyInvitationsParams struct {
	Email          string `json:"email"`
	OrganizationID int64  `json:"organization_id"`
	EngagementID   int64  `json:"engagement_id"`
}

func (q *Queries) MaskPrivacyInvitations(ctx context.Context, arg MaskPrivacyInvitationsParams) (int64, error) {
	result, err := q.db.Exec(ctx, maskPrivacyInvitations, arg.Email, arg.OrganizationID, arg.EngagementID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

